#' Chi-square Test
#'
#' 
#' @param data .
#' @param rc .
#' @param correct .
#' @param a .
#' @param tlt .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$h0} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$T} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$tlt} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$pt} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
ChiSquareTest <- function(
    data,
    rc,
    correct = TRUE,
    a = "0.05",
    tlt = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ChiSquareTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rc)) rc <- jmvcore::resolveQuo(jmvcore::enquo(rc))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rc), rc, NULL))


    options <- ChiSquareTestOptions$new(
        rc = rc,
        correct = correct,
        a = a,
        tlt = tlt)

    analysis <- ChiSquareTestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

